// ---------------------------------------------------------------------------
// R_UnboundValue — the "not found" sentinel (SYMSXP, type=1).
//
// Pattern: Global Sentinel SEXP for Pointer Equality Comparison
// Location: rpart_callback.c:23
//
// Original R API usage (rpart_callback.c:18–28):
//
//   #if R_VERSION < R_Version(4, 5, 0)
//   static SEXP compat_getVar(SEXP sym, SEXP rho, Rboolean inherits)
//   {
//     SEXP val = inherits ? findVar(sym, rho) : findVarInFrame(rho, sym);
//     if (val == R_UnboundValue)                  // <-- line 23
//       error(_("variable '%s' not found"), CHAR(PRINTNAME(sym)));
//     return val;
//   }
//   #define R_getVar(sym, rho, inherits) compat_getVar(sym, rho, inherits)
//   #endif
//
// Real declaration in Rinternals.h line 413:
//   LibExtern SEXP  R_UnboundValue;     /* Unbound marker */
//
// LibExtern expands to `extern` when linking against libR.so.
// In the fake build there is no libR.so, so the variable must be DEFINED
// (not merely declared) in the fake header.
//
// Fake mechanism: a function-local static SEXPREC with type=SYMSXP.
// The make_unbound_value() factory guarantees that:
//   - The SEXPREC is initialized exactly once per process.
//   - Every module-level `static SEXP R_UnboundValue` across all translation
//     units that include this header resolves to the same pointer address.
//   - The address differs from nil_rec (R_NilValue), from names_sym
//     (R_NamesSymbol), and from any heap allocation produced by allocVector /
//     allocMatrix / mkChar (which use std::malloc and therefore never alias
//     a function-local static).
//
// Observable properties (verified against rpart_callback.c usage):
//   R_UnboundValue != nullptr              (safe to hold in a SEXP variable)
//   R_UnboundValue != R_NilValue           (distinct from the nil sentinel)
//   R_UnboundValue != R_NamesSymbol        (distinct from the names symbol)
//   R_UnboundValue != any allocVector()    (heap vs. BSS — always distinct)
//   TYPEOF(R_UnboundValue) == SYMSXP (1)  (consistent with a symbol node)
//
// No accessor (INTEGER, REAL, CHAR, LENGTH, etc.) is ever applied to
// R_UnboundValue in the rpart source.  The `==` comparison at line 23 is
// the only operation performed on it.
//
// Invariant applicability:
//   Invariant 1 (C++ exception errors): triggered at line 24 (error()), not
//     by R_UnboundValue itself.  When val == R_UnboundValue, the code calls
//     error(...) which expands to Rf_error(...) which throws RError.
//   Invariant 2 (arena memory): not triggered.  R_UnboundValue is a
//     function-static SEXPREC in the BSS segment; no arena allocation occurs.
//   Invariant 3 (R Interpreter Items): partially applicable.  The sentinel
//     itself needs no function-pointer bridge; the bridge requirement belongs
//     to findVar and findVarInFrame, which produce the val that is compared
//     against R_UnboundValue.
//
// The primary definition lives in SEXP.h (included above) under the guard
// FAKE_R_UNBOUNDVALUE_DEFINED.  The block below is a guarded fallback for
// the case where this header is included into a translation unit that did
// not previously include SEXP.h.
// ---------------------------------------------------------------------------
#ifndef FAKE_R_UNBOUNDVALUE_DEFINED
#define FAKE_R_UNBOUNDVALUE_DEFINED

inline SEXP make_unbound_value() {
    static SEXPREC unbound_rec = { SYMSXP, 0, 0, 0, NULL };
    return &unbound_rec;
}

/* Every translation unit that includes this header gets its own static
   SEXP R_UnboundValue variable; all point to the same SEXPREC because
   make_unbound_value() uses a function-local static (initialized once,
   process-wide, on first call). */
static SEXP R_UnboundValue = make_unbound_value();

#endif // FAKE_R_UNBOUNDVALUE_DEFINED

// ---------------------------------------------------------------------------
// get_R_UnboundValue — exported C accessor for Python interop.
//
// Python must read the sentinel's pointer address before registering its
// findVarInFrame callback, so that the callback can return the same address
// on lookup failure.  The module-level `static SEXP R_UnboundValue` above is
// not directly visible to Python (it has internal linkage); this extern "C"
// accessor bridges the gap.
//
// Usage in the Python glue layer:
//
//   lib.get_R_UnboundValue.restype  = ctypes.c_void_p
//   lib.get_R_UnboundValue.argtypes = []
//   R_UNBOUND = lib.get_R_UnboundValue()   # integer address of unbound_rec
//
// The Python findVarInFrame callback returns R_UNBOUND on failure; on the C
// side, compat_getVar compares val against R_UnboundValue using pointer ==,
// which succeeds because both sides hold the same address.
//
// This function is guarded by FAKE_GET_R_UNBOUNDVALUE_DEFINED to prevent
// a redefinition error if another fake header (e.g., a future combined
// fake_Rinternals.hpp) also provides it.
// ---------------------------------------------------------------------------
#ifndef FAKE_GET_R_UNBOUNDVALUE_DEFINED
#define FAKE_GET_R_UNBOUNDVALUE_DEFINED

extern "C" inline SEXP get_R_UnboundValue() {
    return R_UnboundValue;
}

#endif // FAKE_GET_R_UNBOUNDVALUE_DEFINED

