// ---------------------------------------------------------------------------
// *** R INTERPRETER ITEM (partial) — findVar / findVarInFrame ***
//
// R_UnboundValue itself requires no Python callback registration.
// However, the two Category E stubs that produce values compared against it —
// findVar and findVarInFrame — do require Python-side registration.
//
// Call chain for init_rpcallback() (rpart_callback.c lines 59-68):
//
//   R_getVar("yback", rho, FALSE)
//     -> compat_getVar(sym, rho, FALSE)          [compat shim, R < 4.5.0]
//       -> findVarInFrame(rho, sym)               [Category E stub]
//       -> if (val == R_UnboundValue)             [sentinel comparison here]
//         -> error("variable '%s' not found")     [throws RError, Invariant 1]
//
// For standard rpart() calls (method != 4), init_rpcallback() is never
// invoked and neither findVar nor findVarInFrame are called; R_UnboundValue
// is never compared against anything.  Registration is only required for
// user-defined split methods (method=4).
//
// Python Interop Notes — full ctypes registration snippet:
//
//   import ctypes
//
//   # Load the shared library built from the fake-header rpart source.
//   lib = ctypes.CDLL("./librpart_fake.so")
//
//   # SEXP is an opaque pointer in Python; use c_void_p.
//   SEXP = ctypes.c_void_p
//
//   # Step 1: retrieve the R_UnboundValue sentinel pointer from the fake lib.
//   # The C-side accessor get_R_UnboundValue() (defined in this header) is
//   # exported with C linkage and is therefore directly callable via ctypes.
//   lib.get_R_UnboundValue.restype  = SEXP
//   lib.get_R_UnboundValue.argtypes = []
//   R_UNBOUND = lib.get_R_UnboundValue()   # int address of unbound_rec
//
//   # Step 2: build a symbol registry.
//   # Maps symbol-SEXP pointer -> value-SEXP pointer.
//   # Populated before each .Call invocation by the Python glue layer.
//   _symbol_registry: dict = {}  # {sym_ptr: val_ptr}
//
//   # Step 3: define and register the findVarInFrame Python callback.
//   # compat_getVar always calls findVarInFrame (inherits=FALSE at all sites).
//   FindVarInFrameFnType = ctypes.CFUNCTYPE(SEXP, SEXP, SEXP)
//
//   def py_findVarInFrame(rho: int, sym: int) -> int:
//       """
//       Look up sym in rho.  Return the registered value SEXP, or
//       R_UnboundValue (== R_UNBOUND) if sym is absent from the registry.
//       Key invariant: returning R_UNBOUND causes compat_getVar to call
//       error(), which throws RError (Invariant 1).
//       """
//       val = _symbol_registry.get(sym)
//       if val is None:
//           return R_UNBOUND   # == R_UnboundValue on the C side
//       return val
//
//   _findVarInFrame_cb = FindVarInFrameFnType(py_findVarInFrame)
//
//   lib.register_findVarInFrame_fn.restype  = None
//   lib.register_findVarInFrame_fn.argtypes = [FindVarInFrameFnType]
//   lib.register_findVarInFrame_fn(_findVarInFrame_cb)
//
//   # The findVar callback (inherits=TRUE path) is registered identically:
//   FindVarFnType = ctypes.CFUNCTYPE(SEXP, SEXP, SEXP)
//
//   def py_findVar(sym: int, rho: int) -> int:
//       val = _symbol_registry.get(sym)
//       if val is None:
//           return R_UNBOUND
//       return val
//
//   _findVar_cb = FindVarFnType(py_findVar)
//
//   lib.register_findVar_fn.restype  = None
//   lib.register_findVar_fn.argtypes = [FindVarFnType]
//   lib.register_findVar_fn(_findVar_cb)
// ---------------------------------------------------------------------------

// --- ArenaFrame usage ---
//
// R_UnboundValue itself has no arena dependency.
// However, the init_rpcallback() .Call-entry wrapper that exercises the
// compat_getVar -> R_UnboundValue code path must declare:
//
//   ArenaFrame _frame;
//
// as its first statement, because init_rpcallback internally calls R_alloc /
// ALLOC scratch allocators (arena-backed).  Once fake_arena.h is available:
//
//   #include "fake_arena.h"
//   extern "C" SEXP init_rpcallback_wrapper(
//           SEXP rhox, SEXP ny, SEXP nr, SEXP expr1x, SEXP expr2x) {
//       ArenaFrame _frame;   // frees all R_alloc/ALLOC scratch on exit
//       try {
//           return init_rpcallback(rhox, ny, nr, expr1x, expr2x);
//       } catch (const RError &e) {
//           // store e.what() for Python, then return sentinel
//           return R_NilValue;
//       }
//   }
//
// Static SEXP singletons (R_UnboundValue, R_NilValue, R_NamesSymbol) survive
// ArenaFrame destruction — they live in the BSS segment, not on the arena.

#endif // FAKE_R_UNBOUNDVALUE_H
